namespace Spayly.Sim.Tests;

// No vitest file covers satellites.ts directly. Satellites.g.cs is generated by godot/tools/gen-satellites.mjs; these
// check the generator carried every row and the fields that are easiest to lose (optional ones, big masses, enums).
// Expected values are copied from src/sim/satellites.ts.
public class SatellitesTests
{
    private static SatelliteElements Sat(string id) => SatelliteTable.Satellites.Single(s => s.Id == id);
    private static MinorBodyElements Minor(string id) => SatelliteTable.MinorBodies.Single(m => m.Id == id);

    [Fact]
    public void Has23MoonsAnd7MinorBodies()
    {
        Assert.Equal(23, SatelliteTable.Satellites.Count);
        Assert.Equal(7, SatelliteTable.MinorBodies.Count);
        Assert.Equal("moon", SatelliteTable.Satellites[0].Id);
        Assert.Equal("charon", SatelliteTable.Satellites[^1].Id);
        Assert.Equal(["ceres", "pallas", "vesta", "pluto", "eris", "haumea", "makemake"], SatelliteTable.MinorBodies.Select(m => m.Id));
    }

    [Fact]
    public void EveryIdIsUnique()
    {
        var ids = SatelliteTable.Satellites.Select(s => s.Id).Concat(SatelliteTable.MinorBodies.Select(m => m.Id)).ToList();
        Assert.Equal(ids.Count, ids.Distinct().Count());
        // Nor may a table id shadow a catalogue planet.
        Assert.Empty(ids.Intersect(Catalog.Specs.Keys));
    }

    [Fact]
    public void IoRowMatchesTheTs()
    {
        var io = Sat("io");
        Assert.Equal("jupiter", io.PrimaryId);
        Assert.Equal(SatelliteFrame.Pole, io.Frame);
        Assert.Equal(268.1, io.PoleRA);
        Assert.Equal(64.5, io.PoleDec);
        Assert.Equal(421800, io.A);
        Assert.Equal(1.762732, io.PeriodDays);
        Assert.Null(io.NodeYr);
        Assert.Equal(1.333, io.ApsisYr);
        Assert.Equal(8.92964876e+22, io.Mass);
        Assert.True(io.Locked);
        Assert.Equal(new BodyVisual { Color = "#e8d17a", Texture = "io.jpg", Albedo = 0.63 }, io.Visual);
    }

    [Fact]
    public void CharonRowMatchesTheTs()
    {
        var charon = Sat("charon");
        Assert.Equal("pluto", charon.PrimaryId);
        Assert.Null(charon.PoleRA);
        Assert.Null(charon.PoleDec);
        Assert.Equal(19600, charon.A);
        Assert.Equal(1.58967982e+21, charon.Mass);
        Assert.Equal(606, charon.Radius);
        Assert.Equal(Surface.Ice, charon.Surface);
        Assert.True(charon.Visual.FillGaps);
    }

    [Fact]
    public void OptionalAndBorrowedMapFieldsSurvive()
    {
        var nereid = Sat("nereid");
        Assert.Equal(SatelliteFrame.Ecliptic, nereid.Frame);
        Assert.Equal(2458849.5, nereid.EpochJd);
        Assert.False(nereid.Locked);
        Assert.Equal(30869289400000000000d, nereid.Mass);
        Assert.Equal("#8f8a84", nereid.Visual.Tint);
        Assert.Equal(0.18, nereid.Visual.Roll);
        Assert.Equal(1.08031854e20, Sat("enceladus").Mass);

        var eris = Minor("eris");
        Assert.Equal(BodyKind.Planet, eris.Kind);
        Assert.Null(eris.Rotation);
        Assert.Equal(25.9, eris.RotationPeriodHours);
        Assert.Equal(10162773800, eris.A);

        var pluto = Minor("pluto");
        Assert.Equal(new Rotation(132.993, -6.163, 302.695, 56.3625225), pluto.Rotation);
        Assert.Null(pluto.RotationPeriodHours);
        Assert.Equal(BodyKind.Asteroid, Minor("pallas").Kind);
    }
}
